import React from 'react';
import { motion } from 'motion/react';
import { Check } from 'lucide-react';
import { useIsDark } from './theme';

export interface CheckboxProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label?: React.ReactNode;
  description?: string;
  disabled?: boolean;
  size?: 'sm' | 'md';
  className?: string;
