 * npm kit entry can export them without pulling app-context toast state
 * (ToastContainer remains an app-level composite, shadcn Toaster style).
 */

import React, { ReactNode } from 'react';
import { Loader2 } from 'lucide-react';
import { Button } from './Button';

export interface EmptyStateProps {
  icon?: ReactNode;
  title: string;
  description: string;
  actionLabel?: string;
  onAction?: () => void;
  persianTitle?: string;
}

export function EmptyState({
  icon,
  title,
  description,
  actionLabel,
  onAction,
  persianTitle,
}: EmptyStateProps) {
  return (
    <div className="flex flex-col items-center justify-center p-8 sm:p-12 text-center rounded-2xl bg-white dark:bg-[#111114] border border-black/[0.06] dark:border-white/[0.055] shadow-[0_8px_24px_rgba(0,0,0,0.03)] dark:shadow-[0_8px_24px_-4px_rgba(0,0,0,0.4)]">
      {icon && (
        <div className="w-12 h-12 rounded-full bg-zinc-100 dark:bg-[#16161B] border border-black/[0.06] dark:border-white/[0.06] text-zinc-600 dark:text-[#92929B] flex items-center justify-center mb-3">
          {icon}
        </div>
      )}
      <h3 className="text-base font-semibold text-zinc-950 dark:text-[#EDEDEF] tracking-tight">
        {title}
      </h3>
      {persianTitle && (
        <p className="font-persian-luxury text-xs text-zinc-400 dark:text-[#5C5C66] mt-0.5">
          {persianTitle}
        </p>
      )}
      <p className="text-xs text-zinc-500 dark:text-[#92929B] mt-1 max-w-xs leading-relaxed">
        {description}
      </p>
      {actionLabel && onAction && (
        <div className="mt-4">
          <Button variant="primary" size="sm" onClick={onAction}>
            {actionLabel}
          </Button>
        </div>
      )}
    </div>
  );
}

export function LoadingState({ message = 'Accessing Safa Space...' }: { message?: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <Loader2 className="w-6 h-6 text-zinc-500 dark:text-[#92929B] animate-spin mb-3" />
      <p className="text-xs text-zinc-500 dark:text-[#8E8E98] tracking-tight">{message}</p>
    </div>
  );
}

/**
 * SAFA — Unified Velvet Modal & Mobile BottomSheet (Build 02.2)
 * Seamless dark depth matching #111114, micro-hairlines, soft diffusion shadows,
 * backed by Radix UI Dialog primitives for full WAI-ARIA focus management & keyboard interaction.
 */

import React, { ReactNode } from 'react';
import * as DialogPrimitive from '@radix-ui/react-dialog';
import { X } from 'lucide-react';
import { IconButton } from './Button';
import { cn } from '../../lib/utils';

export interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  subtitle?: string;
  children: ReactNode;
  maxWidth?: 'sm' | 'md' | 'lg' | 'xl' | '2xl';
  showClose?: boolean;
}

export function Modal({
  isOpen,
  onClose,
  title,
  subtitle,
  children,
  maxWidth = 'md',
  showClose = true,
}: ModalProps) {
  const maxWClass = {
    sm: 'max-w-sm',
    md: 'max-w-md',
    lg: 'max-w-lg',
    xl: 'max-w-xl',
    '2xl': 'max-w-2xl',
  }[maxWidth];

  return (
    <DialogPrimitive.Root open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-50 bg-black/75 backdrop-blur-md data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 overflow-hidden pointer-events-none">
          <DialogPrimitive.Content
            className={cn(
              'pointer-events-auto relative w-full bg-white dark:bg-[#111114] text-zinc-950 dark:text-[#EDEDEF]',
              'border border-black/[0.08] dark:border-white/[0.06]',
              'shadow-[0_24px_50px_rgba(0,0,0,0.14)] dark:shadow-[0_24px_60px_-10px_rgba(0,0,0,0.85),inset_0_1px_0_0_rgba(255,255,255,0.04)]',
              'sm:rounded-3xl rounded-t-[28px] overflow-hidden max-h-[92vh] flex flex-col z-10 pb-safe outline-none',
              'data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:slide-out-to-bottom data-[state=open]:slide-in-from-bottom sm:data-[state=closed]:zoom-out-95 sm:data-[state=open]:zoom-in-95',
              maxWClass
            )}
          >
            {/* Tactile Sheet Drag Handle for Mobile */}
            <div className="sm:hidden pt-3 pb-1 flex justify-center cursor-grab">
              <div className="w-10 h-1 rounded-full bg-zinc-300 dark:bg-white/15" />
            </div>

            {/* Header */}
            {(title || showClose) && (
              <div className="px-5 sm:px-6 pt-3 sm:pt-4 pb-3.5 border-b border-black/[0.06] dark:border-white/[0.05] flex items-center justify-between shrink-0">
                <div>
                  {title && (
                    <DialogPrimitive.Title className="text-lg sm:text-xl font-bold tracking-tight text-zinc-950 dark:text-[#EDEDEF]">
                      {title}
                    </DialogPrimitive.Title>
                  )}
                  {subtitle && (
                    <DialogPrimitive.Description className="text-xs text-zinc-500 dark:text-[#92929B] mt-0.5">
                      {subtitle}
                    </DialogPrimitive.Description>
                  )}
                </div>
                {showClose && (
                  <IconButton
                    icon={<X className="w-4 h-4" />}
                    onClick={onClose}
                    variant="ghost"
                    size="sm"
                    label="Close dialog"
                  />
                )}
              </div>
            )}

            {/* Body */}
            <div className="p-5 sm:p-6 overflow-y-auto no-scrollbar flex-1">
              {children}
            </div>
          </DialogPrimitive.Content>
        </div>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  );
}

