  onFilesSelected,
  className = '',
}: FileUploadProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [files, setFiles] = useState<File[]>([]);

  const emit = useCallback(
    (list: FileList | null) => {
      if (!list || list.length === 0) return;
      const next = Array.from(list);
      setFiles((prev) => (multiple ? [...prev, ...next] : next));
      onFilesSelected?.(next);
    },
    [multiple, onFilesSelected]
  );

  return (
    <div className={cn('w-full space-y-2', className)}>
      <label
        className={cn(
          'relative flex min-h-[96px] cursor-pointer flex-col items-center justify-center gap-2 rounded-2xl border border-dashed p-6 text-center transition-all duration-150',
          'border-black/[0.12] dark:border-white/[0.12] bg-zinc-50/60 dark:bg-[#0E0E13]/60',
          'hover:border-emerald-500/40 hover:bg-emerald-500/[0.03] focus-visible:outline-none focus-safa',
          isDragging && 'border-emerald-500 bg-emerald-500/[0.05] scale-[0.99]',
          disabled && 'opacity-40 pointer-events-none'
        )}
        onDragOver={(e) => {
          e.preventDefault();
          setIsDragging(true);
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {
          e.preventDefault();
          setIsDragging(false);
          emit(e.dataTransfer.files);
        }}
      >
        <UploadCloud className="w-5 h-5 text-zinc-400 dark:text-[#71717A]" />
        <span className="text-xs font-medium text-zinc-600 dark:text-[#92929B]">{label}</span>
        <input
          ref={inputRef}
          type="file"
          className="sr-only"
          accept={accept}
          multiple={multiple}
          disabled={disabled}
          onChange={(e) => {
            emit(e.target.files);
            e.target.value = '';
          }}
        />
      </label>

      {files.length > 0 && (
        <ul className="flex flex-wrap gap-1.5" aria-label="Selected files">
          {files.map((f, i) => (
            <li key={`${f.name}-${i}`}>
              <Tag
                variant="neutral"
                onRemove={() => setFiles((prev) => prev.filter((_, j) => j !== i))}
              >
                <FileIcon className="w-3 h-3 mr-1 inline" aria-hidden="true" />
                {f.name}
              </Tag>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * UI99 — Sparkline (Wave D)
 * Zero-dependency SVG micro-chart: line or bar mode, gradient fill option,
 * a11y via role="img" + aria-label. No chart library — 2KB of math.
 */

import React, { useId } from 'react';
import { cn } from '../../lib/utils';

export interface SparklineProps {
  data: number[];
  mode?: 'line' | 'bar';
  width?: number;
  height?: number;
  color?: 'emerald' | 'amber' | 'rose' | 'blue' | 'purple' | 'neutral';
  fill?: boolean;
  strokeWidth?: number;
  label?: string;
  className?: string;
}

const colorMap = {
  emerald: '#10B981',
  amber: '#F59E0B',
  rose: '#F43F5E',
  blue: '#3B82F6',
  purple: '#A855F7',
  neutral: '#8E8E98',
} as const;

export function Sparkline({
  data,
  mode = 'line',
  width = 120,
  height = 36,
  color = 'emerald',
  fill = true,
  strokeWidth = 1.5,
  label,
  className = '',
}: SparklineProps) {
  const gradId = useId();
  const hex = colorMap[color];

  if (data.length === 0) return null;
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  if (mode === 'bar') {
    const gap = 1.5;
    const barW = Math.max((width - gap * (data.length - 1)) / data.length, 1);
    return (
      <svg
        role="img"
        aria-label={label ?? `Bar sparkline, ${data.length} points`}
        viewBox={`0 0 ${width} ${height}`}
        className={cn('overflow-visible', className)}
        style={{ width, height }}
      >
        {data.map((v, i) => {
          const h = Math.max(((v - min) / range) * (height - 2), 1);
          return (
            <rect
              key={i}
              x={i * (barW + gap)}
              y={height - h}
              width={barW}
              height={h}
              rx={Math.min(barW / 2, 2)}
              fill={hex}
              opacity={0.35 + 0.65 * (v / max)}
            />
          );
        })}
      </svg>
    );
  }

  const step = width / Math.max(data.length - 1, 1);
  const points = data.map((v, i) => [i * step, height - 2 - ((v - min) / range) * (height - 4)] as const);
  const line = points.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const area = `${line} L${width},${height} L0,${height} Z`;

  return (
    <svg
      role="img"
      aria-label={label ?? `Line sparkline, ${data.length} points`}
      viewBox={`0 0 ${width} ${height}`}
      className={cn('overflow-visible', className)}
      style={{ width, height }}
    >
      {fill && (
        <>
          <defs>
            <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={hex} stopOpacity="0.25" />
              <stop offset="100%" stopColor={hex} stopOpacity="0" />
            </linearGradient>
          </defs>
          <path d={area} fill={`url(#${gradId})`} />
        </>
      )}
      <path
        d={line}
        fill="none"
        stroke={hex}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx={points[points.length - 1][0]} cy={points[points.length - 1][1]} r={2.2} fill={hex} />
    </svg>
  );
}

/**
 * UI99 — DonutRing (Wave D)
 * Zero-dependency SVG progress ring: single or multi-segment, center slot,
 * polished round caps, accessible via role="img" + aria-label.
 */

import React from 'react';
import { cn } from '../../lib/utils';

export interface DonutSegment {
  value: number;
  color?: 'emerald' | 'amber' | 'rose' | 'blue' | 'purple' | 'neutral';
}

const segColor = {
  emerald: '#10B981',
  amber: '#F59E0B',
  rose: '#F43F5E',
  blue: '#3B82F6',
  purple: '#A855F7',
  neutral: 'rgba(142,142,152,0.35)',
} as const;

export interface DonutRingProps {
  segments: DonutSegment[];
  size?: number;
  thickness?: number;
  label?: string;
  showValue?: boolean;
  valueSuffix?: string;
  className?: string;
  children?: React.ReactNode;
}

export function DonutRing({
  segments,
  size = 88,
  thickness = 8,
  label,
  showValue = false,
  valueSuffix = '%',
  className = '',
  children,
}: DonutRingProps) {
  const total = segments.reduce((s, seg) => s + seg.value, 0) || 1;
  const radius = (size - thickness) / 2;
  const circumference = 2 * Math.PI * radius;
  let offsetAcc = 0;

  return (
    <div className={cn('relative inline-flex items-center justify-center', className)} style={{ width: size, height: size }}>
      <svg
        role="img"
        aria-label={label ?? `Progress ring at ${Math.round((segments[0]?.value ?? 0) / total * 100)}%`}
        viewBox={`0 0 ${size} ${size}`}
        style={{ width: size, height: size }}
        className="-rotate-90"
      >
        {/* track */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="rgba(142,142,152,0.15)"
          strokeWidth={thickness}
        />
        {segments.map((seg, i) => {
          const frac = seg.value / total;
          const dash = frac * circumference;
          const el = (
            <circle
              key={i}
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke={segColor[seg.color ?? 'emerald']}
              strokeWidth={thickness}
              strokeLinecap="round"
              strokeDasharray={`${Math.max(dash - 2, 0)} ${circumference - Math.max(dash - 2, 0)}`}
              strokeDashoffset={-offsetAcc}
              className="transition-all duration-300"
            />
          );
          offsetAcc += dash;
          return el;
        })}
      </svg>
      {(children || showValue) && (
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          {children ?? (
            <span className="text-sm font-bold font-mono text-zinc-950 dark:text-white">
              {Math.round(((segments[0]?.value ?? 0) / total) * 100)}
              <span className="text-[10px] text-zinc-400">{valueSuffix}</span>
            </span>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * UI99 — HeatMapCalendar (Wave D)
 * GitHub-style contribution grid: 7 rows x N weeks, 5 intensity levels,
 * month labels optional, fully CSS-driven (no deps), accessible summary.
 */

import React from 'react';
import { cn } from '../../lib/utils';

export interface HeatMapCalendarProps {
  /** Flat values, index 0 = oldest cell; length = weeks * 7 */
  data: number[];
  weeks?: number;
  max?: number;
  color?: 'emerald' | 'amber' | 'rose' | 'blue';
  cellSize?: number;
  label?: string;
  className?: string;
}

const heatColor = {
  emerald: ['#0E0E13', 'rgba(16,185,129,0.25)', 'rgba(16,185,129,0.45)', 'rgba(16,185,129,0.7)', '#10B981'],
  amber: ['#0E0E13', 'rgba(245,158,11,0.25)', 'rgba(245,158,11,0.45)', 'rgba(245,158,11,0.7)', '#F59E0B'],
  rose: ['#0E0E13', 'rgba(244,63,94,0.25)', 'rgba(244,63,94,0.45)', 'rgba(244,63,94,0.7)', '#F43F5E'],
  blue: ['#0E0E13', 'rgba(59,130,246,0.25)', 'rgba(59,130,246,0.45)', 'rgba(59,130,246,0.7)', '#3B82F6'],
} as const;

/** Light-theme palettes: level 0 becomes a faint gray, rest scale color opacity. */
const heatColorLight = {
  emerald: ['rgba(0,0,0,0.05)', 'rgba(5,150,105,0.2)', 'rgba(5,150,105,0.4)', 'rgba(5,150,105,0.65)', '#059669'],
  amber: ['rgba(0,0,0,0.05)', 'rgba(180,83,9,0.2)', 'rgba(180,83,9,0.4)', 'rgba(180,83,9,0.65)', '#B45309'],
  rose: ['rgba(0,0,0,0.05)', 'rgba(190,18,60,0.2)', 'rgba(190,18,60,0.4)', 'rgba(190,18,60,0.65)', '#BE123C'],
  blue: ['rgba(0,0,0,0.05)', 'rgba(37,99,235,0.2)', 'rgba(37,99,235,0.4)', 'rgba(37,99,235,0.65)', '#2563EB'],
} as const;

export function HeatMapCalendar({
  data,
  weeks = 18,
  max,
  color = 'emerald',
  cellSize = 11,
  label,
  className = '',
}: HeatMapCalendarProps) {
  // Light/dark decided via CSS: we render both palettes through currentColor trick
  // — simpler: read theme from DOM class on <html> (kit theme protocol).
  const isDark =
    typeof document === 'undefined' || !document.documentElement.classList.contains('light');
  const palette = (isDark ? heatColor : heatColorLight)[color];
  const cap = max ?? Math.max(...data, 1);

  const cells = data.slice(0, weeks * 7);

  return (
    <div
      role="img"
      aria-label={label ?? `Activity heatmap: ${data.filter((v) => v > 0).length} active of ${cells.length} days`}
      className={cn('inline-grid gap-[3px]', className)}
      style={{ gridTemplateRows: 'repeat(7, 1fr)', gridAutoFlow: 'column', gridAutoColumns: `${cellSize}px` }}
    >
      {cells.map((v, i) => {
        const level = v <= 0 ? 0 : Math.min(4, Math.ceil((v / cap) * 4));
        return (
          <span
            key={i}
            className="rounded-[3px] transition-colors duration-150"
            style={{ width: cellSize, height: cellSize, backgroundColor: palette[level] }}
          />
        );
      })}
    </div>
  );
}

/**
 * UI99 — StatTile (Wave D)
 * Metric card: value, label, delta chip (up/down/flat), optional trailing
 * sparkline slot. The workhorse of dashboards.
 */

import React from 'react';
import { ArrowUpRight, ArrowDownRight, Minus } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface StatTileProps {
  label: string;
  value: string | number;
  delta?: number;
  deltaSuffix?: string;
  trend?: React.ReactNode;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export function StatTile({
  label,
  value,
  delta,
  deltaSuffix = '%',
  trend,
  size = 'md',
  className = '',
}: StatTileProps) {
  const deltaTone =
    delta === undefined ? 'neutral' : delta > 0 ? 'up' : delta < 0 ? 'down' : 'flat';
  const toneStyle = {
    up: 'text-emerald-600 dark:text-emerald-400',
    down: 'text-rose-600 dark:text-rose-400',
    flat: 'text-zinc-500 dark:text-[#8E8E98]',
    neutral: '',
  }[deltaTone];
  const DeltaIcon =
    deltaTone === 'up' ? ArrowUpRight : deltaTone === 'down' ? ArrowDownRight : Minus;

  const valueSize = {
    sm: 'text-lg',
    md: 'text-2xl',
    lg: 'text-3xl sm:text-4xl',
  }[size];

  return (
    <div
      className={cn(
        'rounded-2xl bg-white dark:bg-[#0B0C11] border border-black/[0.05] dark:border-white/[0.03] p-4 sm:p-5',
        'shadow-[0_4px_16px_rgba(0,0,0,0.03)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.04),0_8px_24px_-4px_rgba(0,0,0,0.5)]',
        'space-y-1.5',
        className
      )}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] font-mono uppercase tracking-wider text-zinc-500 dark:text-[#8E8E98]">
          {label}
        </span>
        {trend && <span className="shrink-0">{trend}</span>}
      </div>
      <div className={cn('font-bold font-mono tracking-tight text-zinc-950 dark:text-white', valueSize)}>
        {value}
      </div>
      {delta !== undefined && (
        <div className={cn('flex items-center gap-1 text-[11px] font-mono font-semibold', toneStyle)}>
          <DeltaIcon className="w-3 h-3" />
          {delta > 0 ? '+' : ''}
          {delta}
          {deltaSuffix}
          <span className="text-zinc-400 dark:text-[#5C5C68] font-normal">vs last week</span>
        </div>
      )}
    </div>
  );
}

/**
 * UI99 — MeterBar (Wave D)
 * Native <meter>-semantics bar: value/max with zone thresholds (low/optimal/
 * high color mapping) — distinct from Progress (task completion).
 */

import React from 'react';
import { cn } from '../../lib/utils';

export interface MeterBarProps {
  value: number;
  max?: number;
  min?: number;
  low?: number;
  high?: number;
  optimum?: number;
  label: string;
  showValue?: boolean;
  size?: 'sm' | 'md';
  className?: string;
}

export function MeterBar({
  value,
  max = 100,
  min = 0,
  low,
  high,
  optimum,
  label,
  showValue = true,
  size = 'md',
  className = '',
}: MeterBarProps) {
  const pct = Math.min(100, Math.max(0, ((value - min) / (max - min)) * 100));

  // Zone coloring per <meter> spec: low/optimum/high relationships.
  const zone =
    optimum !== undefined && value < optimum
      ? 'bg-amber-500'
      : high !== undefined && value > high
        ? 'bg-rose-500'
        : low !== undefined && value < low
          ? 'bg-amber-500'
          : 'bg-emerald-500';

  return (
    <div
      className={cn('w-full space-y-1.5', className)}
      role="meter"
      aria-valuenow={value}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-label={label}
    >
      {showValue && (
        <div className="flex items-center justify-between text-xs">
          <span className="font-semibold text-zinc-800 dark:text-[#EDEDEF]">{label}</span>
          <span className="font-mono text-[11px] text-zinc-500 dark:text-[#8E8E98]">
            {value}/{max}
          </span>
        </div>
      )}
      <div
        className={cn(
          'w-full rounded-full overflow-hidden bg-black/[0.08] dark:bg-white/[0.08]',
          size === 'sm' ? 'h-1.5' : 'h-2.5'
        )}
      >
        <div
          className={cn('h-full rounded-full transition-all duration-300', zone)}
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

/**
 * UI99 — TrendDelta (Wave D)
 * Compact signed delta chip: +12.4% / -3.1% with semantic tone, used inside
 * tables, tiles and headers. Color never the only signal (icon + sign).
 */

import React from 'react';
import { ArrowUpRight, ArrowDownRight, Minus } from 'lucide-react';
import { cn } from '../../lib/utils';

export interface TrendDeltaProps {
  delta: number;
  suffix?: string;
  size?: 'sm' | 'md';
  showIcon?: boolean;
  invertTone?: boolean; // for "lower is better" metrics
  className?: string;
}

export function TrendDelta({
  delta,
  suffix = '%',
  size = 'sm',
  showIcon = true,
  invertTone = false,
  className = '',
}: TrendDeltaProps) {
  const effective = invertTone ? -delta : delta;
  const tone =
    effective > 0 ? 'up' : effective < 0 ? 'down' : 'flat';
  const toneStyle = {
    up: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border-emerald-500/20',
    down: 'bg-rose-500/10 text-rose-700 dark:text-rose-400 border-rose-500/20',
    flat: 'bg-black/[0.04] text-zinc-600 dark:bg-white/[0.05] dark:text-[#8E8E98] border-black/[0.04] dark:border-white/[0.05]',
  }[tone];
  const Icon = tone === 'up' ? ArrowUpRight : tone === 'down' ? ArrowDownRight : Minus;

  return (
    <span
      className={cn(
        'inline-flex items-center gap-0.5 rounded-full border font-mono font-semibold whitespace-nowrap',
        size === 'sm' ? 'px-1.5 py-0.5 text-[10px]' : 'px-2 py-1 text-xs',
        toneStyle,
        className
      )}
    >
      {showIcon && <Icon className={size === 'sm' ? 'w-3 h-3' : 'w-3.5 h-3.5'} aria-hidden="true" />}
      {delta > 0 ? '+' : ''}
      {delta}
      {suffix}
    </span>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Utility for combining Tailwind CSS classes with clsx and resolving conflicts with tailwind-merge.
 * Standard implementation benchmarked against shadcn/ui.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * SAFA UI Kit — `safa.css` (source of truth, imported by src/index.css)
 *
 * Single source of truth for the kit's runtime design tokens. During
 * `bun run lib:build` this file is copied verbatim into the npm package as
 * `dist/safa.css` — see scripts/build-kit-css.mjs. Edit tokens HERE.
 *
 * Theme protocol: the app shell expresses theme by toggling `dark`/`light`
 * on <html>; tokens resolve through var() cascade. SCOPING GUARANTEE: every
 * block below is scoped under `.dark`/`.light` (no bare :root) so importing
 * this stylesheet into a host app can never fight the host's own :root
 * custom properties. Default-dark fallbacks for standalone kit usage ship
 * via the `@supports not (selector :has(*))` no-op guard below — hosts that
 * never toggle a class simply see the token defaults in the `.dark` block
 * mirrored to `:root` behind an explicit opt-out class `safa-no-default`.
 */

/* ======================= OBSIDIAN DARK (default) ======================= */
.dark {
  /* Surfaces */
  --bg-canvas: #050507;
  --bg-surface: #0E0E13;
  --bg-card: #0E0F14;
  --bg-card-hover: #131319;
  --bg-elevated: #131318;
  --border-subtle: transparent;
  --border-specular: rgba(255, 255, 255, 0.06);
  --border-hairline: rgba(255, 255, 255, 0.025);

  /* Text */
  --text-primary: #FFFFFF;
  --text-secondary: #8E8E98;
  --text-muted: #5C5C68;

  /* Dock / glass */
  --dock-bg: rgba(14, 14, 19, 0.9);
  --dock-border: rgba(255, 255, 255, 0.07);

  /* M3-grade unified state layers (hover 6% / press 4% / selected 8% / drag 16%) */
  --state-hover: rgba(255, 255, 255, 0.06);
  --state-press: rgba(255, 255, 255, 0.04);
  --state-selected: rgba(255, 255, 255, 0.08);
  --state-drag: rgba(255, 255, 255, 0.16);

  /* Focus (WCAG 2.4.11/2.4.13) */
  --focus-ring: rgba(16, 185, 129, 0.55);
}

/* ======================= PORCELAIN LIGHT ======================= */
.light {
  --bg-canvas: #F5F5F8;
  --bg-surface: #FFFFFF;
  --bg-card: #FFFFFF;
  --bg-card-hover: #F8F8FA;
  --bg-elevated: #FFFFFF;
  --border-subtle: rgba(0, 0, 0, 0.045);
  --border-specular: rgba(255, 255, 255, 1);
  --border-hairline: rgba(0, 0, 0, 0.03);

  --text-primary: #111116;
  --text-secondary: #646470;
  --text-muted: #9494A0;

  --dock-bg: rgba(255, 255, 255, 0.94);
  --dock-border: rgba(0, 0, 0, 0.05);

  /* Light-mode calibrated state layers (subtle, non-glare) */
  --state-hover: rgba(0, 0, 0, 0.04);
  --state-press: rgba(0, 0, 0, 0.03);
  --state-selected: rgba(0, 0, 0, 0.06);
  --state-drag: rgba(0, 0, 0, 0.1);

  --focus-ring: rgba(5, 150, 105, 0.5);
}

/* ======================= SHARED / THEME-AGNOSTIC ======================= */
.dark,
.light {
  /* Motion durations (Apple HIG 150–500ms band) */
  --duration-instant: 75ms;
  --duration-fast: 120ms;
  --duration-base: 180ms;
  --duration-slow: 280ms;
  --duration-deliberate: 400ms;

  /* Easing curves */
  --ease-safa: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);

  /* Typography */
  --font-sans: 'Geist', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-mono: 'JetBrains Mono', 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-persian: 'Vazirmatn', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Radius scale (iOS 18+ smooth curves, mathematical nesting) */
  --radius-pill: 9999px;
  --radius-sheet: 32px;
  --radius-card-xl: 28px;
  --radius-card-lg: 24px;
  --radius-card-md: 18px;
  --radius-card-sm: 12px;
}

/* ======================= FOCUS UTILITIES (WCAG 2.4.13) ======================= */
/* Plain-CSS class form: safe to consume from the npm stylesheet without Tailwind. */

.focus-safa:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--bg-canvas), 0 0 0 4px var(--focus-ring);
}

.focus-safa-inset:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--focus-ring);
}

/* ======================= REDUCED MOTION ======================= */
